preConditionHook:
// IN A STRONG TREND, BUY A DIP OF A FIXED SIZE RATHER THAN A PATTERN: price
// trades a set fraction of the trend's OWN AVERAGE PRIOR PULLBACK below the
// running high. Sized to the trend's behaviour, so the entry adapts as the
// trend's pullbacks grow. Brooks says "equal to or slightly less than the
// average prior pullbacks", hence the 0.9 default.
//
// NO TICK UNIT IS USED DESPITE THE KEY'S NAME. The source states the entry in
// ticks; the engine exposes no tick size to a strategy, and the merged rule
// had already replaced the fixed tick distance with a fraction of the trend's
// measured average pullback, which is instrument-independent and is what is
// coded here. The key is kept because it is the merged key.
//
// A GENUINE EXTENSION OF MaxPullbackDepthBelowThreshold's give-back tracker
// rather than a use of it: that rule keeps the MAXIMUM completed pullback,
// this needs the running SUM and COUNT so it can average them. A pullback
// COMPLETES when a new extreme is made -- on a bar that takes out the running
// high the depth just accumulated is folded into the sum and the live depth
// is cleared. Zero-depth pullbacks are not counted, so a run of consecutive
// new-high bars does not drag the average down.
//
// THE LEG RESET IS THE ALWAYS-IN FLIP, the standing corpus decision, inlined
// here as TrendDurationBars inlines it and with the same inputs so every
// consumer reads the same state: the direction FLIPS on consecutiveBars
// consecutive STRONG TREND BARS -- body at least bodyFraction of the bar's
// own range and BOTH tails no more than tailFraction of it -- holds until the
// opposite flip, and is UNDEFINED (aiDir = 0) until the first flip ever. The
// sum and the count clear on the flip, so the average is always the CURRENT
// trend's own behaviour.
//
// Under the standing convention the resting limit order becomes signal-bar
// close and next-bar open, so the rule fires on the bar whose own low reaches
// the level and the entry is the following open. The running high is extended
// before the test, so a bar that makes a new high and later sells off deep
// enough still fires -- which is what a resting order would have done.
//
// pbCntUp > 0 guards the division and also keeps the rule silent until the
// trend has shown at least one pullback to average.
//
// Mirrored: the long side buys the dip below the bull leg's running high, the
// short side sells the rally above the bear leg's running low.
//
// Deepest bar touched: consecutiveBars - 1.
allBull = true;
allBear = true;
for (kk = 0; kk < (int)consecutiveBars; ++kk) {
    rng = high[kk] - low[kk];
    if (el_le(close[kk], open[kk])) allBull = false;
    if (el_lt(close[kk] - open[kk], bodyFraction * rng)) allBull = false;
    if (el_gt(high[kk] - close[kk], tailFraction * rng)) allBull = false;
    if (el_gt(open[kk] - low[kk], tailFraction * rng)) allBull = false;
    if (el_ge(close[kk], open[kk])) allBear = false;
    if (el_lt(open[kk] - close[kk], bodyFraction * rng)) allBear = false;
    if (el_gt(close[kk] - low[kk], tailFraction * rng)) allBear = false;
    if (el_gt(high[kk] - open[kk], tailFraction * rng)) allBear = false;
}
flipped = false;
if (allBull && aiDir != 1) {
    aiDir = 1;
    flipped = true;
}
if (allBear && aiDir != -1 && flipped == false) {
    aiDir = -1;
    flipped = true;
}
if (flipped) {
    runHigh = high[0];
    runLow = low[0];
    curPbUp = 0.0;
    curPbDn = 0.0;
    pbSumUp = 0.0;
    pbSumDn = 0.0;
    pbCntUp = 0;
    pbCntDn = 0;
}
if (flipped == false) {
    if (el_gt(high[0], runHigh)) {
        if (el_gt(curPbUp, 0.0)) {
            pbSumUp = pbSumUp + curPbUp;
            pbCntUp = pbCntUp + 1;
        }
        curPbUp = 0.0;
        runHigh = high[0];
    } else {
        if (el_gt(runHigh - low[0], curPbUp)) curPbUp = runHigh - low[0];
    }
    if (el_lt(low[0], runLow)) {
        if (el_gt(curPbDn, 0.0)) {
            pbSumDn = pbSumDn + curPbDn;
            pbCntDn = pbCntDn + 1;
        }
        curPbDn = 0.0;
        runLow = low[0];
    } else {
        if (el_gt(high[0] - runLow, curPbDn)) curPbDn = high[0] - runLow;
    }
}
avgPbUp = 0.0;
if (pbCntUp > 0) avgPbUp = pbSumUp / pbCntUp;
avgPbDn = 0.0;
if (pbCntDn > 0) avgPbDn = pbSumDn / pbCntDn;
dipUp = (aiDir == 1) && (pbCntUp > 0) && el_le(low[0], runHigh - avgPullbackFraction * avgPbUp);
dipDn = (aiDir == -1) && (pbCntDn > 0) && el_ge(high[0], runLow + avgPullbackFraction * avgPbDn);
